// Package pgx holds DBTX, the interface that repositories generated by kanna-orm for pgx run on. Each generated package
// declares its DBTX as this one, or as CopyDBTX when kanna-orm writes a Copy for it, so a single value serves all of
// them, as when a dependency injector provides it once.
package pgx

import (
	"context"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// DBTX is what repositories run on: *pgxpool.Pool, *pgx.Conn, or pgx.Tx. If you wrap a transaction in your own
// DBTX, give it an `Unwrap() DBTX` method that returns the transaction, so that methods that lock rows can tell they
// run inside one.
type DBTX interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// CopyDBTX is a DBTX that can also copy rows. Repositories in a package where kanna-orm writes a Copy run on it:
// *pgxpool.Pool, *pgx.Conn, or pgx.Tx, as with DBTX.
type CopyDBTX interface {
	DBTX
	CopyFrom(ctx context.Context, tableName pgx.Identifier, columnNames []string, rowSrc pgx.CopyFromSource) (int64,
		error)
}
